#include <chrono>
#include <cstdio>
#include <functional>
#include <iostream>

class ScopeTimer
{
public:
    explicit ScopeTimer(const char* name) : m_name{ name }, m_start{ std::chrono::steady_clock::now() } {}
    ~ScopeTimer()
    {
        const auto ms{ std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - m_start).count() };
        std::cout << m_name << " took " << ms << " ms\n";
    }
    ScopeTimer(const ScopeTimer&) = delete;
    ScopeTimer& operator=(const ScopeTimer&) = delete;

private:
    const char* m_name{};
    std::chrono::steady_clock::time_point m_start{};
};

